                _pk[1] = __floats2bfloat162_rn(o[v_1 * 8 + 2], o[v_1 * 8 + 3]);
                _pk[2] = __floats2bfloat162_rn(o[v_1 * 8 + 4], o[v_1 * 8 + 5]);
                _pk[3] = __floats2bfloat162_rn(o[v_1 * 8 + 6], o[v_1 * 8 + 7]);
                *reinterpret_cast<uint4*>(&((__nv_bfloat16*)(output + (dst_base + v_1 * 8)))[0]) = *reinterpret_cast<uint4*>(&_pk[0]);
            }
        }
        if (part == 0) {
            float lse_scaled = ((lse_out == -1e+30f) ? lse_out : lse_out * lse_scale);
            *(reinterpret_cast<float*>(out_lse + row) + (0)) = lse_scaled;
        }
    }
}

