cudaError_t configure() {
  cudaError_t status = cudaFuncSetAttribute(decode::kernel_sm120_dsv4_nvfp4_sparse_mla_decode_h128, cudaFuncAttributeMaxDynamicSharedMemorySize,
                                            kDecodeSmemBytes);
  if (status != cudaSuccess) return status;
  return cudaFuncSetAttribute(decode_dual::kernel_sm120_dsv4_nvfp4_sparse_mla_decode_h128_dual, cudaFuncAttributeMaxDynamicSharedMemorySize,
                              kDecodeSmemBytes);
}

cudaError_t launch_decode(const DecodeArgs& a, bool dual, dim3 grid, cudaStream_t stream) {
  if (dual) {
    decode_dual::kernel_sm120_dsv4_nvfp4_sparse_mla_decode_h128_dual<<<grid, kDecodeThreads, kDecodeSmemBytes, stream>>>(a.q, a.kv_cache, a.indices, a.extra_kv_cache, a.extra_indices, a.topk_length, a.extra_topk_length, a.attn_sink, a.output, a.out_lse, a.mid_out, a.mid_lse, a.topk, a.extra_topk, a.page_size, a.page_stride_bytes, a.extra_page_size, a.extra_page_stride_bytes, a.scratch_split_stride, a.chunks_per_block, a.sm_scale, a.lse_scale, a.write_direct);
  } else {
    decode::kernel_sm120_dsv4_nvfp4_sparse_mla_decode_h128<<<grid, kDecodeThreads, kDecodeSmemBytes, stream>>>(a.q, a.kv_cache, a.indices, a.extra_kv_cache, a.extra_indices, a.topk_length, a.extra_topk_length, a.attn_sink, a.output, a.out_lse, a.mid_out, a.mid_lse, a.topk, a.extra_topk, a.page_size, a.page_stride_bytes, a.extra_page_size, a.extra_page_stride_bytes, a.scratch_split_stride, a.chunks_per_block, a.sm_scale, a.lse_scale, a.write_direct);
  }
  return cudaGetLastError();
}

cudaError_t launch_merge(const MergeArgs& a, dim3 grid, cudaStream_t stream) {
  merge::kernel_sm120_dsv4_nvfp4_sparse_mla_merge_h128<<<grid, kMergeThreads, kMergeSmemBytes, stream>>>(a.mid_out, a.mid_lse, a.attn_sink, a.output, a.out_lse, a.num_splits, a.scratch_split_stride, a.lse_scale);
